<script setup lang="ts">
import HarvestAssessment from '../components/HarvestAssessment.vue'
import RidgeAnomalies from '../components/RidgeAnomalies.vue'
import FieldSelector from '../components/FieldSelector.vue'
import {computed,ref,watch} from 'vue'
import {useRoute,useRouter} from 'vue-router'
import {Sprout} from 'lucide-vue-next'
import RidgeDetection from '../components/RidgeDetection.vue'
import {useFarm} from '../stores/farm'
const farm=useFarm(),route=useRoute(),router=useRouter(),selected=ref(''),filter=ref('')
watch(()=>route.query.crop,crop=>{filter.value=typeof crop==='string'?crop:''},{immediate:true})
watch(()=>route.query.id,id=>{selected.value=typeof id==='string'?id:''},{immediate:true})
const detailTab=computed(()=>route.query.tab==='issues'?'issues':'overview')
function setTab(tab:string){router.replace({query:{...route.query,tab}})}
const current=computed(()=>farm.ridges.find(r=>r.id===selected.value)),visible=computed(()=>farm.ridges.filter(r=>!filter.value||r.cropId===filter.value))
function pick(id:string){router.replace({query:{...route.query,id}})}
</script><template><div class="filters"><FieldSelector/><select v-model="filter" aria-label="地图作物筛选"><option value="">全部作物</option><option v-for="c in farm.crops" :key="c.id" :value="c.id">{{c.name}}</option></select><RouterLink to="/management" class="primary push">新增种植</RouterLink></div><div class="map-layout"><section class="panel map-panel"><div class="panel-title"><h2>种植布局图</h2><span class="muted">{{farm.ridges.length}} 条田垄</span></div><div class="legend"><span>● 在种</span><span>◌ 空垄</span><span>● 异常</span><span>● 长势偏离</span><span class="harvest-legend">◆ 采收提醒</span></div><div class="field-grid"><button v-for="r in visible" :key="r.id" class="ridge" :class="{'harvest-ready':farm.assessment(r)?.harvestReady,selected:selected===r.id,vacant:!r.active,danger:!!farm.assessment(r)?.issues.some(i=>!i.startsWith('长势')),slow:!!farm.assessment(r)?.issues.some(i=>i.startsWith('长势'))&&!farm.assessment(r)?.issues.some(i=>!i.startsWith('长势'))}" @click="pick(r.id)" :aria-label="r.number+'号垄，'+farm.status(r)+(farm.harvestAssessment(r)?.score!=null?'，综合成熟评分'+farm.harvestAssessment(r)!.score!.toFixed(1)+'分':'')+(farm.assessment(r)?.harvestReady?'，采收提醒':'')"><span>{{String(r.number).padStart(2,'0')}}</span><Sprout :size="25"/><small>{{!r.active?'空垄':farm.crops.find(c=>c.id===r.cropId)?.name}}</small><span v-if="r.active" class="ridge-maturity" :class="{ready:farm.assessment(r)?.harvestReady}">{{farm.harvestAssessment(r)?.score==null?'成熟度待检测':(farm.assessment(r)?.harvestReady?'◆ ':'')+'综合 '+farm.harvestAssessment(r)!.score!.toFixed(1)+'分'}}</span></button></div></section><section class="panel detail-panel" v-if="current"><div class="panel-title"><h2>{{current.number}}号垄</h2><span class="badge" :class="{warning:farm.status(current)!=='生长正常'}">{{farm.status(current)}}</span></div><p>{{farm.cropName(current.cropId)}}</p><div class="tabs" role="group" aria-label="田垄详情类别"><button :class="{active:detailTab==='overview'}" :aria-pressed="detailTab==='overview'" @click="setTab('overview')">监测详情</button><button :class="{active:detailTab==='issues'}" :aria-pressed="detailTab==='issues'" @click="setTab('issues')">异常与处理记录</button></div><RidgeAnomalies v-if="detailTab==='issues'" :key="farm.fieldId+current.id" :ridge="current"/><template v-else><HarvestAssessment :ridge="current"/><div class="rule-reminders"><span v-for="issue in farm.assessment(current)?.issues" :key="issue" class="badge warning">{{issue}}</span><span v-if="farm.assessment(current)?.harvestReady" class="badge">综合成熟评分达到采收参考</span></div><section v-if="current.active&&farm.crops.find(c=>c.id===current!.cropId)?.maturityProfile?.kind!=='leafy'" class="ridge-fruit-summary"><div class="panel-title"><h2>果实阶段分布</h2><span v-if="farm.assessment(current)?.harvestReady" class="badge harvest-badge">达到采收提醒阈值</span></div><template v-if="farm.assessment(current)?.maturity!=null"><div class="ridge-fruit-total"><strong>{{farm.assessment(current)!.maturity!.toFixed(1)}}<small>%</small></strong><span>{{current.mature}} / {{current.fruitCount}} 个有效果实</span></div><div class="progress-track"><i :style="{width:farm.assessment(current)!.maturity+'%'}"/></div><div class="fruit-stage-counts"><span>成熟 <b>{{current.mature}}</b></span><span>转色 <b>{{current.turning}}</b></span><span>未成熟 <b>{{current.immature}}</b></span><span>不确定 <b>{{current.unknown}}</b></span></div></template><p v-else class="muted">暂无有效成熟度数据</p></section><RidgeDetection :ridge-id="current.id" :updated-at="farm.dashboard?.updatedAt"/><dl><div><dt>种植批次</dt><dd>{{current.batch}}</dd></div><div><dt>种植日期</dt><dd>{{current.plantedAt}}</dd></div><div><dt>登记苗数</dt><dd>{{current.plants}} 株</dd></div><div><dt>数据质量</dt><dd>{{current.quality}}</dd></div></dl><template v-if="current.active&&current.quality!=='待首次巡检'"><div class="detail-stats"><div><span>较上次增长</span><strong>{{farm.assessment(current)?.comparable?(current.growthCm!>0?'+':'')+current.growthCm:'待对比'}}<small v-if="farm.assessment(current)?.comparable">cm</small></strong></div><div><span>叶片面积</span><strong>{{current.leafArea}}<small>cm²</small></strong></div></div><dl><div v-if="farm.crops.find(c=>c.id===current!.cropId)?.maturityProfile?.kind!=='leafy'"><dt>可见果实</dt><dd>{{current.fruitCount}} 个</dd></div><div><dt>病斑对象</dt><dd>{{current.lesions}} 个</dd></div><div><dt>上次检测</dt><dd>{{current.previousSampledAt?new Date(current.previousSampledAt).toLocaleDateString('zh-CN'):'暂无对比记录'}}</dd></div><div><dt>本次检测</dt><dd>{{new Date(current.sampledAt).toLocaleDateString('zh-CN')}}</dd></div><div><dt>有效检测植株</dt><dd>{{current.plantSampleCount}} 株</dd></div><div><dt>病叶 / 检测叶片</dt><dd>{{current.diseasedLeafCount}} / {{current.leafSampleCount}} 片</dd></div><div v-if="farm.crops.find(c=>c.id===current!.cropId)?.maturityProfile?.kind!=='leafy'"><dt>病果 / 检测果实</dt><dd>{{current.diseasedFruitCount}} / {{current.fruitCount}} 个</dd></div><div v-if="farm.assessment(current)?.nextInspection"><dt>下次巡检</dt><dd>{{new Date(farm.assessment(current)!.nextInspection!).toLocaleDateString('zh-CN')}}</dd></div></dl></template><div v-else class="empty">{{current.active?'待首次巡检，暂不进行长势评价。':'该田垄暂无在种作物。'}}</div><RouterLink :to="'/management?ridge='+current.id" class="primary">{{current.active?'登记采收':'创建种植批次'}} →</RouterLink><p class="muted">新增记录后，工作台统计会同步更新。</p></template></section><section class="panel empty" v-else>选择左侧田垄，查看种植详情。</section></div></template>